//! Replays the in-process menu oracle scripts of `fixtures/menu_oracle/` (generated by `oracle/MenuOracleBase.java` from
//! `oracle/menu_scripts/NAME.txt` through the REAL vanilla menus; regenerate with `scripts/menu-oracle.sh NAME`) on our menus.
//! See `common::menu_oracle` for the replay.

use crate::common::menu_oracle::replay;

/// A chest opened through its block: clicks of every kind, drags, drops and two seeded random sessions.
#[test]
fn chest_menu_script_matches_vanilla() {
    let ops = replay("menu_oracle", "chest_smoke");
    assert!(ops > 150, "fixture has {ops} ops");
}

/// BLOCK, TICK, GAMERULE, SEED, MAP, RECIPE and the level broadcasts.
#[test]
fn menu_ops_script_matches_vanilla() {
    let ops = replay("menu_oracle", "menu_ops");
    assert!(ops > 30, "fixture has {ops} ops");
}

/// The loom: every banner colour with each pattern item and dye, the patterns that need no item, six layers, selection kept by
/// value, invalid button ids, taking the result with its sound, quick moves, close and random sessions.
#[test]
fn loom_menu_script_matches_vanilla() {
    let ops = replay("menu_oracle", "loom");
    assert!(ops > 1000, "fixture has {ops} ops");
}
